create table if not exists public.finance_transaction_budget_allocations (id uuid primary key default gen_random_uuid(), transaction_id uuid not null references public.finance_transactions(id) on delete cascade, budget_id uuid not null references public.department_budgets(id) on delete cascade, allocated_amount numeric(14,2) not null check (allocated_amount > 0), created_by uuid not null default auth.uid(), created_at timestamptz not null default now(), unique(transaction_id,budget_id));
create index if not exists finance_tx_budget_alloc_tx_idx on public.finance_transaction_budget_allocations(transaction_id);
create index if not exists finance_tx_budget_alloc_budget_idx on public.finance_transaction_budget_allocations(budget_id);
alter table public.finance_transaction_budget_allocations enable row level security;
create policy finance_tx_budget_alloc_read on public.finance_transaction_budget_allocations for select using (public.finance_can_view());
create policy finance_tx_budget_alloc_insert on public.finance_transaction_budget_allocations for insert with check (public.finance_can_manage() and created_by = auth.uid());
create policy finance_tx_budget_alloc_update on public.finance_transaction_budget_allocations for update using (public.finance_can_manage()) with check (public.finance_can_manage());
create policy finance_tx_budget_alloc_delete on public.finance_transaction_budget_allocations for delete using (public.finance_can_manage());
create or replace view public.v_planning_budget_reconciliation with (security_invoker=true) as select b.id as budget_id,b.plan_id,b.department,b.category,b.project_name,b.activity_name,b.period_start,b.period_end,coalesce(sum(case when t.direction in ('out','expense','sortie','debit') and t.status in ('paid','completed','validated','approved','confirmed') then a.allocated_amount else 0 end),0) as linked_actual_expenses,coalesce(sum(case when t.direction in ('in','income','entree','credit','revenue') and t.status in ('paid','completed','validated','approved','confirmed') then a.allocated_amount else 0 end),0) as linked_actual_revenue,count(distinct t.id) filter(where t.status in ('paid','completed','validated','approved','confirmed')) as linked_transactions, b.actual_amount as manually_entered_actual_amount,b.actual_revenue as manually_entered_actual_revenue,coalesce(sum(a.allocated_amount),0) as total_allocated from public.department_budgets b left join public.finance_transaction_budget_allocations a on a.budget_id=b.id left join public.finance_transactions t on t.id=a.transaction_id group by b.id,b.plan_id,b.department,b.category,b.project_name,b.activity_name,b.period_start,b.period_end,b.actual_amount,b.actual_revenue;